{
  "name": "patchpad",
  "version": "1.0.0",
  "description": "Browser-based editor for long incident reports",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "dev": "node src/server.js"
  },
  "keywords": ["editor", "incident", "report"],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "express": "^5.1.0",
    "better-sqlite3": "^9.2.2",
    "body-parser": "^1.20.2"
  }
}

const sqlite3 = require('sqlite3').verbose();
const fs = require('fs');
const path = require('path');

const DB_PATH = path.join(__dirname, '../patchpad.db');
const SEED_PATH = '/assets/incident_seed.json';

let db = null;

function getDb() {
  if (!db) {
    db = new sqlite3.Database(DB_PATH, (err) => {
      if (err) console.error('Database connection error:', err);
    });
    db.configure('busyTimeout', 5000);
  }
  return db;
}

function promisify(fn) {
  return (...args) => new Promise((resolve, reject) => {
    fn(...args, (err, result) => {
      if (err) reject(err);
      else resolve(result);
    });
  });
}

function run(sql, params = []) {
  return promisify((cb) => {
    getDb().run(sql, params, function(err) {
      if (err) cb(err);
      else cb(null, { lastID: this.lastID, changes: this.changes });
    });
  })();
}

function get(sql, params = []) {
  return promisify((cb) => {
    getDb().get(sql, params, cb);
  })();
}

function all(sql, params = []) {
  return promisify((cb) => {
    getDb().all(sql, params, cb);
  })();
}

function expandSeedContent(seed) {
  const { sections, generatedLineCount, generatedLineTemplate, tailSections } = seed.document;
  const lines = [...sections];

  for (let i = 1; i <= generatedLineCount; i++) {
    const line = generatedLineTemplate.replace('{n}', i);
    lines.push(line);
  }

  lines.push(...tailSections);
  return lines.join('\n');
}

async function initializeDatabase() {
  try {
    await run(`
      CREATE TABLE IF NOT EXISTS documents (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        author TEXT NOT NULL,
        summary TEXT,
        currentRevision INTEGER NOT NULL DEFAULT 1,
        createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
        updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    await run(`
      CREATE TABLE IF NOT EXISTS revisions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        documentId TEXT NOT NULL,
        revisionNumber INTEGER NOT NULL,
        content TEXT NOT NULL,
        createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (documentId) REFERENCES documents(id),
        UNIQUE(documentId, revisionNumber)
      )
    `);

    // Check if we need to seed
    const existingDoc = await get('SELECT * FROM documents WHERE id = ?', ['incident-alpha']);
    if (!existingDoc) {
      const seedData = JSON.parse(fs.readFileSync(SEED_PATH, 'utf8'));
      const content = expandSeedContent(seedData);

      await run(
        `INSERT INTO documents (id, title, author, summary, currentRevision) VALUES (?, ?, ?, ?, 1)`,
        [
          seedData.document.id,
          seedData.document.title,
          seedData.document.author,
          seedData.document.summary
        ]
      );

      await run(
        `INSERT INTO revisions (documentId, revisionNumber, content) VALUES (?, 1, ?)`,
        [seedData.document.id, content]
      );
    }
  } catch (error) {
    console.error('Database initialization error:', error);
    throw error;
  }
}

async function listDocuments() {
  return all('SELECT id, title, author FROM documents ORDER BY updatedAt DESC');
}

async function getDocument(documentId) {
  const doc = await get('SELECT * FROM documents WHERE id = ?', [documentId]);
  if (!doc) return null;

  const revision = await get(
    'SELECT content FROM revisions WHERE documentId = ? AND revisionNumber = ?',
    [documentId, doc.currentRevision]
  );

  return {
    id: doc.id,
    title: doc.title,
    author: doc.author,
    summary: doc.summary,
    content: revision ? revision.content : '',
    currentRevision: doc.currentRevision
  };
}

async function saveDocument(documentId, content, baseRevision) {
  const doc = await get('SELECT currentRevision FROM documents WHERE id = ?', [documentId]);
  if (!doc) throw new Error('Document not found');

  if (doc.currentRevision !== baseRevision) {
    throw { statusCode: 409, message: 'Conflict: Document has been modified' };
  }

  const currentContent = await get(
    'SELECT content FROM revisions WHERE documentId = ? AND revisionNumber = ?',
    [documentId, baseRevision]
  );

  if (currentContent && currentContent.content === content) {
    return { revision: baseRevision, status: 'unchanged' };
  }

  const newRevision = baseRevision + 1;
  await run(
    'INSERT INTO revisions (documentId, revisionNumber, content) VALUES (?, ?, ?)',
    [documentId, newRevision, content]
  );

  await run(
    'UPDATE documents SET currentRevision = ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?',
    [newRevision, documentId]
  );

  return { revision: newRevision, status: 'saved' };
}

async function getRevisionHistory(documentId) {
  return all(
    `SELECT revisionNumber, createdAt FROM revisions WHERE documentId = ? ORDER BY revisionNumber DESC`,
    [documentId]
  );
}

async function getRevision(documentId, revisionNumber) {
  return get(
    'SELECT content FROM revisions WHERE documentId = ? AND revisionNumber = ?',
    [documentId, revisionNumber]
  );
}

async function restoreRevision(documentId, revisionNumber) {
  const revision = await get(
    'SELECT content FROM revisions WHERE documentId = ? AND revisionNumber = ?',
    [documentId, revisionNumber]
  );

  if (!revision) throw new Error('Revision not found');

  const doc = await get('SELECT currentRevision FROM documents WHERE id = ?', [documentId]);
  const newRevision = doc.currentRevision + 1;

  await run(
    'INSERT INTO revisions (documentId, revisionNumber, content) VALUES (?, ?, ?)',
    [documentId, newRevision, revision.content]
  );

  await run(
    'UPDATE documents SET currentRevision = ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?',
    [newRevision, documentId]
  );

  return { revision: newRevision, content: revision.content };
}

module.exports = {
  initializeDatabase,
  listDocuments,
  getDocument,
  saveDocument,
  getRevisionHistory,
  getRevision,
  restoreRevision,
  getDb
};

const express = require('express');
const path = require('path');
const bodyParser = require('body-parser');
const db = require('./db');

const app = express();
const PORT = process.env.PORT || 3000;

app.use(bodyParser.json({ limit: '50mb' }));
app.use(bodyParser.text({ limit: '50mb' }));
app.use(express.static(path.join(__dirname, '../public')));

// API Routes

app.get('/api/documents', async (req, res) => {
  try {
    const documents = await db.listDocuments();
    res.json(documents);
  } catch (error) {
    console.error('Error listing documents:', error);
    res.status(500).json({ error: 'Failed to list documents' });
  }
});

app.get('/api/documents/:id', async (req, res) => {
  try {
    const document = await db.getDocument(req.params.id);
    if (!document) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json(document);
  } catch (error) {
    console.error('Error fetching document:', error);
    res.status(500).json({ error: 'Failed to fetch document' });
  }
});

app.post('/api/documents/:id/save', async (req, res) => {
  try {
    const { id } = req.params;
    const { content, baseRevision, documentId } = req.body;

    // Validate input
    if (typeof content !== 'string') {
      return res.status(400).json({ error: 'Content must be a string' });
    }
    if (typeof baseRevision !== 'number' || !Number.isInteger(baseRevision)) {
      return res.status(400).json({ error: 'baseRevision must be an integer' });
    }
    if (documentId && documentId !== id) {
      return res.status(400).json({ error: 'Document ID mismatch' });
    }

    const result = await db.saveDocument(id, content, baseRevision);
    res.json(result);
  } catch (error) {
    if (error.statusCode === 409) {
      return res.status(409).json({ error: error.message });
    }
    console.error('Error saving document:', error);
    res.status(500).json({ error: 'Failed to save document' });
  }
});

app.get('/api/documents/:id/history', async (req, res) => {
  try {
    const history = await db.getRevisionHistory(req.params.id);
    res.json(history);
  } catch (error) {
    console.error('Error fetching history:', error);
    res.status(500).json({ error: 'Failed to fetch history' });
  }
});

app.get('/api/documents/:id/revisions/:revisionNumber', async (req, res) => {
  try {
    const { id, revisionNumber } = req.params;
    const revision = await db.getRevision(id, parseInt(revisionNumber));
    if (!revision) {
      return res.status(404).json({ error: 'Revision not found' });
    }
    res.json(revision);
  } catch (error) {
    console.error('Error fetching revision:', error);
    res.status(500).json({ error: 'Failed to fetch revision' });
  }
});

app.post('/api/documents/:id/restore/:revisionNumber', async (req, res) => {
  try {
    const { id, revisionNumber } = req.params;
    const result = await db.restoreRevision(id, parseInt(revisionNumber));
    res.json(result);
  } catch (error) {
    console.error('Error restoring revision:', error);
    res.status(500).json({ error: 'Failed to restore revision' });
  }
});

// Serve main page
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, '../public/index.html'));
});

// Initialize database and start server
async function start() {
  try {
    await db.initializeDatabase();
    app.listen(PORT, '0.0.0.0', () => {
      console.log(`PatchPad server running on http://0.0.0.0:${PORT}`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

start();

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #dbeafe;
  --danger: #dc2626;
  --danger-hover: #b91c1c;
  --success: #16a34a;
  --warning: #f59e0b;
  --text: #1f2937;
  --text-secondary: #6b7280;
  --border: #e5e7eb;
  --bg: #ffffff;
  --bg-secondary: #f9fafb;
  --bg-hover: #f3f4f6;
  --status-saved: #10b981;
  --status-unsaved: #f59e0b;
  --conflict-bg: #fef3c7;
  --conflict-border: #fcd34d;
  --line-number-bg: #f3f4f6;
  --line-number-text: #9ca3af;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

/* Header */
.app-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.report-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--text);
  flex: 1;
  min-width: 300px;
}

.header-controls {
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
}

.save-status {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--status-saved);
  color: white;
}

.save-status.unsaved {
  background: var(--status-unsaved);
}

.revision-display {
  font-size: 12px;
  color: var(--text-secondary);
}

/* Main content area */
.main-content {
  display: flex;
  flex: 1;
  overflow: hidden;
  gap: 0;
}

.editor-wrapper {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  background: var(--bg);
}

.revision-sidebar {
  width: 250px;
  border-left: 1px solid var(--border);
  background: var(--bg-secondary);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 16px;
}

.revision-sidebar h2 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 12px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 8px;
}

.revision-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.revision-item {
  padding: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  transition: background 0.2s;
}

.revision-item:hover {
  background: var(--bg-hover);
  border-color: var(--primary);
}

.revision-item-number {
  font-weight: 600;
  color: var(--primary);
}

.revision-item-time {
  font-size: 11px;
  color: var(--text-secondary);
  display: block;
  margin-top: 4px;
}

/* Toolbar */
.editor-toolbar {
  display: flex;
  gap: 16px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
  flex-wrap: wrap;
  align-items: center;
}

.toolbar-group {
  display: flex;
  gap: 8px;
  align-items: center;
}

.find-input, .replace-input {
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 12px;
  min-width: 120px;
  transition: border-color 0.2s;
}

.find-input:focus, .replace-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary-light);
}

.find-count {
  font-size: 12px;
  color: var(--text-secondary);
  min-width: 40px;
}

.replace-controls {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* Buttons */
.btn {
  padding: 6px 12px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg);
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  user-select: none;
}

.btn:hover:not(:disabled) {
  background: var(--bg-hover);
  border-color: var(--primary);
  color: var(--primary);
}

.btn:active:not(:disabled) {
  background: var(--primary-light);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.btn-primary:hover:not(:disabled) {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
  color: white;
}

.btn-danger {
  background: var(--danger);
  color: white;
  border-color: var(--danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
  color: white;
}

.btn-close {
  position: absolute;
  top: 12px;
  right: 12px;
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: var(--text-secondary);
  padding: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-close:hover {
  color: var(--text);
}

/* Editor container */
.editor-container {
  display: flex;
  flex: 1;
  overflow: hidden;
  position: relative;
  background: var(--bg);
}

.line-numbers {
  width: 60px;
  background: var(--line-number-bg);
  border-right: 1px solid var(--border);
  padding: 8px 0;
  text-align: right;
  overflow: hidden;
  user-select: none;
  color: var(--line-number-text);
  font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.5;
}

.line-number {
  padding: 0 8px;
  display: block;
  height: 1.5em;
  white-space: nowrap;
}

.editor-pane {
  flex: 1;
  overflow: auto;
  position: relative;
  font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.5;
  background: var(--bg);
}

.editor-pane:focus {
  outline: none;
}

.cursor-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 10;
}

.cursor {
  position: absolute;
  width: 2px;
  background: var(--primary);
  animation: blink 1s infinite;
  pointer-events: none;
}

.cursor.inactive {
  background: var(--text-secondary);
  animation: none;
}

@keyframes blink {
  0%, 49%, 100% {
    opacity: 1;
  }
  50%, 99% {
    opacity: 0;
  }
}

.text-content {
  padding: 8px;
  white-space: pre-wrap;
  word-wrap: break-word;
  color: var(--text);
  z-index: 1;
  position: relative;
}

.editor-input {
  position: absolute;
  opacity: 0;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
  pointer-events: none;
  z-index: -1;
}

.selection {
  position: absolute;
  background: rgba(37, 99, 235, 0.2);
  pointer-events: none;
  z-index: 5;
}

.find-match {
  background: rgba(245, 158, 11, 0.3);
  outline: 1px solid var(--warning);
}

.find-match.current {
  background: rgba(245, 158, 11, 0.5);
  outline: 2px solid var(--warning);
  outline-offset: -1px;
}

/* Status bar */
.status-bar {
  padding: 8px 16px;
  border-top: 1px solid var(--border);
  background: var(--bg-secondary);
  font-size: 12px;
  color: var(--text-secondary);
}

#cursor-position {
  font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace;
}

/* Notifications */
.notification {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.conflict-notification {
  background: rgba(0, 0, 0, 0.5);
}

.notification-content {
  background: var(--bg);
  border: 2px solid var(--conflict-border);
  border-radius: 8px;
  padding: 20px;
  max-width: 400px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.notification-content h3 {
  color: var(--warning);
  margin-bottom: 8px;
}

.notification-content p {
  color: var(--text-secondary);
  margin-bottom: 16px;
  font-size: 13px;
}

.notification-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

/* Modal */
.modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-content {
  background: var(--bg);
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  max-width: 600px;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  position: relative;
  width: 90%;
}

.modal-header {
  padding: 20px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.modal-header h2 {
  font-size: 16px;
  color: var(--text);
}

.preview-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace;
  font-size: 12px;
  white-space: pre-wrap;
  word-wrap: break-word;
  color: var(--text);
  background: var(--bg-secondary);
  line-height: 1.5;
}

.modal-footer {
  padding: 16px 20px;
  border-top: 1px solid var(--border);
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  flex-shrink: 0;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-secondary);
}

/* Responsive */
@media (max-width: 1200px) {
  .revision-sidebar {
    width: 200px;
  }

  .toolbar-group {
    flex-wrap: wrap;
  }
}

@media (max-width: 800px) {
  .revision-sidebar {
    display: none;
  }

  .app-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .header-controls {
    width: 100%;
    justify-content: space-between;
  }
}

class PatchPadEditor {
  constructor() {
    this.documentId = 'incident-alpha';
    this.content = '';
    this.currentRevision = 1;
    this.baseRevision = 1;
    this.isSaved = true;
    this.lines = [];

    // Cursor and selection
    this.carets = [{ pos: 0, anchor: 0 }]; // Array of {pos, anchor}

    // Undo/Redo
    this.history = [];
    this.historyIndex = -1;
    this.lastTypedPos = null;
    this.lastTypedTime = 0;

    // Find/Replace
    this.findQuery = '';
    this.findMatches = [];
    this.findCurrentIndex = -1;
    this.replaceQuery = '';
    this.showReplace = false;

    // Preview state
    this.previewRevision = null;
    this.previewContent = '';

    // Conflict state
    this.hasConflict = false;
    this.conflictDraft = '';

    this.initializeElements();
    this.attachEventListeners();
    this.loadDocument();
  }

  initializeElements() {
    // Main elements
    this.editorPane = document.getElementById('editor-pane');
    this.textContent = document.getElementById('text-content');
    this.editorInput = document.getElementById('editor-input');
    this.lineNumbers = document.getElementById('line-numbers');
    this.cursorLayer = document.getElementById('cursor-layer');

    // UI elements
    this.saveStatus = document.getElementById('save-status');
    this.revisionDisplay = document.getElementById('revision-display');
    this.cursorPosition = document.getElementById('cursor-position');
    this.reportTitle = document.getElementById('report-title');

    // Buttons
    this.btnSave = document.getElementById('btn-save');
    this.btnUndo = document.getElementById('btn-undo');
    this.btnRedo = document.getElementById('btn-redo');
    this.btnFindNext = document.getElementById('btn-find-next');
    this.btnFindPrev = document.getElementById('btn-find-prev');
    this.btnReplaceToggle = document.getElementById('btn-replace-toggle');
    this.btnReplaceOne = document.getElementById('btn-replace-one');
    this.btnReplaceAll = document.getElementById('btn-replace-all');

    // Find/Replace inputs
    this.findInput = document.getElementById('find-input');
    this.findCount = document.getElementById('find-count');
    this.replaceInput = document.getElementById('replace-input');
    this.replaceControls = document.getElementById('replace-controls');

    // Revision history
    this.revisionList = document.getElementById('revision-list');

    // Conflict notification
    this.conflictNotification = document.getElementById('conflict-notification');
    this.conflictMessage = document.getElementById('conflict-message');
    this.btnReload = document.getElementById('btn-reload');
    this.btnKeepDraft = document.getElementById('btn-keep-draft');

    // Preview modal
    this.previewModal = document.getElementById('preview-modal');
    this.previewTitle = document.getElementById('preview-title');
    this.previewBody = document.getElementById('preview-body');
    this.btnRestorePreview = document.getElementById('btn-restore-preview');
    this.btnCancelPreview = document.getElementById('btn-cancel-preview');
    this.btnClosePreview = document.getElementById('btn-close-preview');
  }

  attachEventListeners() {
    // Editor input
    this.editorPane.addEventListener('click', (e) => this.handleClick(e));
    this.editorPane.addEventListener('mousedown', (e) => this.handleMouseDown(e));
    this.editorPane.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.editorPane.addEventListener('mouseup', () => this.handleMouseUp());
    this.editorPane.addEventListener('scroll', () => this.syncLineNumbers());

    this.editorInput.addEventListener('input', (e) => this.handleInput(e));
    this.editorInput.addEventListener('keydown', (e) => this.handleKeyDown(e));
    this.editorInput.addEventListener('keyup', () => this.updateCursor());

    // Focus management
    this.editorPane.addEventListener('keydown', (e) => {
      if (!this.hasConflict) {
        this.editorInput.focus();
        this.handleKeyDown(e);
      }
    });

    // Buttons
    this.btnSave.addEventListener('click', () => this.save());
    this.btnUndo.addEventListener('click', () => this.undo());
    this.btnRedo.addEventListener('click', () => this.redo());
    this.btnFindNext.addEventListener('click', () => this.findNext());
    this.btnFindPrev.addEventListener('click', () => this.findPrev());
    this.btnReplaceToggle.addEventListener('click', () => this.toggleReplace());
    this.btnReplaceOne.addEventListener('click', () => this.replaceOne());
    this.btnReplaceAll.addEventListener('click', () => this.replaceAll());

    // Find/Replace
    this.findInput.addEventListener('input', () => this.updateFind());
    this.findInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.shiftKey ? this.findPrev() : this.findNext();
      } else if (e.key === 'Escape') {
        this.editorInput.focus();
      }
    });

    this.replaceInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        this.replaceOne();
      }
    });

    // Conflict notification
    this.btnReload.addEventListener('click', () => this.reloadDocument());
    this.btnKeepDraft.addEventListener('click', () => this.dismissConflict());

    // Preview modal
    this.btnClosePreview.addEventListener('click', () => this.closePreview());
    this.btnCancelPreview.addEventListener('click', () => this.closePreview());
    this.btnRestorePreview.addEventListener('click', () => this.confirmRestore());

    // Focus editor on load
    this.editorPane.addEventListener('click', () => this.editorInput.focus());
  }

  async loadDocument() {
    try {
      const response = await fetch(`/api/documents/${this.documentId}`);
      if (!response.ok) throw new Error('Failed to load document');

      const doc = await response.json();
      this.content = doc.content;
      this.currentRevision = doc.currentRevision;
      this.baseRevision = doc.currentRevision;
      this.reportTitle.textContent = doc.title;

      this.updateContent();
      this.refreshRevisionHistory();
      this.editorInput.focus();
    } catch (error) {
      console.error('Error loading document:', error);
      alert('Failed to load document');
    }
  }

  updateContent() {
    this.lines = this.content.split('\n');
    this.render();
    this.updateCursor();
  }

  render() {
    // Update text content
    this.textContent.textContent = this.content;

    // Update line numbers
    this.updateLineNumbers();

    // Update undo/redo buttons
    this.btnUndo.disabled = this.historyIndex <= 0;
    this.btnRedo.disabled = this.historyIndex >= this.history.length - 1;
  }

  updateLineNumbers() {
    const numLines = this.lines.length;
    let html = '';
    for (let i = 1; i <= numLines; i++) {
      html += `<div class="line-number">${i}</div>`;
    }
    this.lineNumbers.innerHTML = html;
  }

  syncLineNumbers() {
    this.lineNumbers.scrollTop = this.editorPane.scrollTop;
  }

  handleClick(e) {
    if (e.target === this.textContent) {
      const pos = this.getPositionFromClick(e);
      const isMulti = e.altKey || e.ctrlKey || e.metaKey;

      if (isMulti) {
        this.addCaret(pos);
      } else {
        this.setCaret(pos);
      }

      this.editorInput.focus();
    }
  }

  handleMouseDown(e) {
    if (e.target === this.textContent) {
      this.mouseDown = true;
      const pos = this.getPositionFromClick(e);
      if (!e.shiftKey && !e.ctrlKey && !e.metaKey) {
        this.carets = [{ pos, anchor: pos }];
      }
    }
  }

  handleMouseMove(e) {
    if (this.mouseDown && e.target === this.textContent) {
      const pos = this.getPositionFromClick(e);
      if (this.carets.length > 0) {
        this.carets[this.carets.length - 1].pos = pos;
      }
      this.render();
      this.updateCursor();
    }
  }

  handleMouseUp() {
    this.mouseDown = false;
  }

  getPositionFromClick(e) {
    const rect = this.textContent.getBoundingClientRect();
    const paneRect = this.editorPane.getBoundingClientRect();

    const x = e.clientX - rect.left + (this.editorPane.scrollLeft - paneRect.left + rect.left);
    const y = e.clientY - rect.top + this.editorPane.scrollTop;

    // Approximate position based on line and column
    const lineHeight = parseInt(getComputedStyle(this.textContent).lineHeight);
    const charWidth = 7.8; // Approximate for monospace fonts

    const line = Math.floor(y / lineHeight);
    const col = Math.floor(x / charWidth);

    let pos = 0;
    for (let i = 0; i < Math.min(line, this.lines.length); i++) {
      pos += this.lines[i].length + 1; // +1 for newline
    }
    pos += Math.min(col, this.lines[line]?.length || 0);

    return Math.min(pos, this.content.length);
  }

  setCaret(pos) {
    this.carets = [{ pos: this.clampPos(pos), anchor: this.clampPos(pos) }];
    this.updateCursor();
  }

  addCaret(pos) {
    pos = this.clampPos(pos);
    const existing = this.carets.find(c => c.pos === pos);
    if (!existing) {
      this.carets.push({ pos, anchor: pos });
    }
    this.updateCursor();
  }

  clampPos(pos) {
    return Math.max(0, Math.min(pos, this.content.length));
  }

  handleInput(e) {
    const now = Date.now();
    const timeSinceLastType = now - this.lastTypedTime;

    // Save to history if:
    // 1. First input or
    // 2. More than 300ms since last input (new action) or
    // 3. Position changed significantly (new caret location)
    const shouldGroup = this.lastTypedPos !== null && 
                        timeSinceLastType < 300 &&
                        Math.abs(this.carets[0].pos - this.lastTypedPos) <= 1;

    if (this.historyIndex === -1 || !shouldGroup) {
      this.saveToHistory();
    }

    this.lastTypedTime = now;
    this.lastTypedPos = this.carets[0].pos;

    this.markUnsaved();
    this.render();
  }

  handleKeyDown(e) {
    if (this.hasConflict) {
      if (e.key === 'Escape') this.reloadDocument();
      return;
    }

    // Handle keyboard shortcuts
    if (e.ctrlKey || e.metaKey) {
      switch (e.key.toLowerCase()) {
        case 's':
          e.preventDefault();
          this.save();
          return;
        case 'z':
          e.preventDefault();
          this.undo();
          return;
        case 'y':
        case 'Z':
          if (e.shiftKey) {
            e.preventDefault();
            this.redo();
          }
          return;
        case 'f':
          e.preventDefault();
          this.findInput.focus();
          this.findInput.select();
          return;
        case 'h':
          e.preventDefault();
          this.toggleReplace();
          return;
      }
    }

    if (e.key === 'Escape' && this.findInput === document.activeElement) {
      this.editorInput.focus();
      return;
    }

    if (e.key === 'Tab') {
      e.preventDefault();
      if (e.shiftKey) {
        this.decreaseIndent();
      } else {
        this.insertText('\t');
      }
      return;
    }

    if (e.key === 'Enter') {
      e.preventDefault();
      this.insertText('\n');
      return;
    }

    if (e.key === 'Backspace') {
      e.preventDefault();
      this.delete(true);
      return;
    }

    if (e.key === 'Delete') {
      e.preventDefault();
      this.delete(false);
      return;
    }

    // Arrow keys
    if (e.key.startsWith('Arrow')) {
      e.preventDefault();
      this.handleArrowKey(e.key, e.shiftKey, e.ctrlKey || e.metaKey, e.altKey);
      return;
    }

    if (e.key === 'Home') {
      e.preventDefault();
      this.handleHome(e.shiftKey);
      return;
    }

    if (e.key === 'End') {
      e.preventDefault();
      this.handleEnd(e.shiftKey);
      return;
    }

    // Regular text input
    if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
      e.preventDefault();
      this.insertText(e.key);
    }
  }

  insertText(text) {
    const selections = this.getSelections();
    let offset = 0;

    for (const sel of selections) {
      const start = Math.min(sel.start, sel.end);
      const end = Math.max(sel.start, sel.end);
      const deleteCount = end - start;

      this.content = this.content.slice(0, start - offset) + text + this.content.slice(end - offset);
      offset += deleteCount - text.length;
    }

    // Move all carets
    let newPos = this.carets[0].anchor + text.length;
    this.carets = [{ pos: newPos, anchor: newPos }];

    this.updateContent();
    this.handleInput({});
  }

  delete(isBackspace) {
    const selections = this.getSelections();

    if (selections.some(sel => sel.start !== sel.end)) {
      // Delete selection
      this.insertText('');
    } else {
      // Delete character
      let offset = 0;
      for (const caret of this.carets) {
        const pos = caret.pos;
        if (isBackspace && pos > 0) {
          this.content = this.content.slice(0, pos - 1 - offset) + this.content.slice(pos - offset);
          offset += 1;
          caret.pos = pos - 1;
        } else if (!isBackspace && pos < this.content.length) {
          this.content = this.content.slice(0, pos - offset) + this.content.slice(pos + 1 - offset);
          offset += 1;
        }
      }
      caret.anchor = caret.pos;
    }

    this.updateContent();
    this.handleInput({});
  }

  handleArrowKey(key, shift, ctrl, alt) {
    for (const caret of this.carets) {
      let newPos = caret.pos;

      if (key === 'ArrowLeft') {
        if (ctrl || alt) {
          newPos = this.getPrevWordStart(newPos);
        } else {
          newPos = Math.max(0, newPos - 1);
        }
      } else if (key === 'ArrowRight') {
        if (ctrl || alt) {
          newPos = this.getNextWordStart(newPos);
        } else {
          newPos = Math.min(this.content.length, newPos + 1);
        }
      } else if (key === 'ArrowUp') {
        newPos = this.moveUp(newPos);
      } else if (key === 'ArrowDown') {
        newPos = this.moveDown(newPos);
      }

      if (shift) {
        caret.pos = newPos;
      } else {
        caret.pos = newPos;
        caret.anchor = newPos;
      }
    }

    this.updateCursor();
    this.render();
  }

  handleHome(shift) {
    for (const caret of this.carets) {
      const lineStart = this.getLineStart(caret.pos);
      const firstNonSpace = this.getFirstNonSpaceInLine(caret.pos);

      const newPos = caret.pos === lineStart ? firstNonSpace : lineStart;

      if (shift) {
        caret.pos = newPos;
      } else {
        caret.pos = newPos;
        caret.anchor = newPos;
      }
    }

    this.updateCursor();
    this.render();
  }

  handleEnd(shift) {
    for (const caret of this.carets) {
      const newPos = this.getLineEnd(caret.pos);

      if (shift) {
        caret.pos = newPos;
      } else {
        caret.pos = newPos;
        caret.anchor = newPos;
      }
    }

    this.updateCursor();
    this.render();
  }

  decreaseIndent() {
    const selections = this.getSelections();
    let offset = 0;

    for (const sel of selections) {
      const lineStart = this.getLineStart(Math.min(sel.start, sel.end));
      if (this.content[lineStart] === '\t') {
        this.content = this.content.slice(0, lineStart - offset) + this.content.slice(lineStart + 1 - offset);
        offset += 1;
      }
    }

    this.updateContent();
    this.handleInput({});
  }

  moveUp(pos) {
    const lineStart = this.getLineStart(pos);
    const col = pos - lineStart;
    const prevLineStart = this.getLineStart(lineStart - 1);
    const prevLineEnd = this.getLineEnd(prevLineStart);
    const prevLineLength = prevLineEnd - prevLineStart;

    return Math.max(0, prevLineStart + Math.min(col, prevLineLength));
  }

  moveDown(pos) {
    const lineEnd = this.getLineEnd(pos);
    const lineStart = this.getLineStart(pos);
    const col = pos - lineStart;
    const nextLineStart = lineEnd + 1;
    const nextLineEnd = this.getLineEnd(nextLineStart);
    const nextLineLength = nextLineEnd - nextLineStart;

    return Math.min(this.content.length, nextLineStart + Math.min(col, nextLineLength));
  }

  getLineStart(pos) {
    let lineStart = pos;
    while (lineStart > 0 && this.content[lineStart - 1] !== '\n') {
      lineStart--;
    }
    return lineStart;
  }

  getLineEnd(pos) {
    let lineEnd = pos;
    while (lineEnd < this.content.length && this.content[lineEnd] !== '\n') {
      lineEnd++;
    }
    return lineEnd;
  }

  getFirstNonSpaceInLine(pos) {
    const lineStart = this.getLineStart(pos);
    let col = lineStart;
    while (col < this.getLineEnd(pos) && /\s/.test(this.content[col])) {
      col++;
    }
    return col;
  }

  getPrevWordStart(pos) {
    if (pos === 0) return 0;
    pos--;
    while (pos > 0 && /\s/.test(this.content[pos])) pos--;
    while (pos > 0 && !/\s/.test(this.content[pos])) pos--;
    if (pos > 0 && /\s/.test(this.content[pos])) pos++;
    return pos;
  }

  getNextWordStart(pos) {
    if (pos >= this.content.length) return this.content.length;
    while (pos < this.content.length && !/\s/.test(this.content[pos])) pos++;
    while (pos < this.content.length && /\s/.test(this.content[pos])) pos++;
    return pos;
  }

  getSelections() {
    return this.carets.map(c => ({
      start: c.anchor,
      end: c.pos
    }));
  }

  updateCursor() {
    this.cursorLayer.innerHTML = '';

    if (this.carets.length === 0) return;

    for (let i = 0; i < this.carets.length; i++) {
      const caret = this.carets[i];
      const pos = caret.pos;
      const anchor = caret.anchor;

      const { line, col } = this.getLineAndColumn(pos);
      this.cursorPosition.textContent = `Line ${line + 1}, Column ${col + 1}`;

      // Create cursor element
      const cursor = document.createElement('div');
      cursor.className = 'cursor' + (i > 0 ? ' inactive' : '');

      const charWidth = 7.8;
      const lineHeight = 21;

      cursor.style.left = (8 + col * charWidth) + 'px';
      cursor.style.top = (8 + line * lineHeight) + 'px';
      cursor.style.height = lineHeight + 'px';

      this.cursorLayer.appendChild(cursor);

      // Draw selection
      if (anchor !== pos) {
        const { line: anchorLine, col: anchorCol } = this.getLineAndColumn(anchor);
        this.drawSelection(Math.min(anchorLine, line), Math.min(anchorCol, col),
                          Math.max(anchorLine, line), Math.max(anchorCol, col));
      }
    }

    this.syncLineNumbers();
  }

  getLineAndColumn(pos) {
    let line = 0;
    let col = 0;

    for (let i = 0; i < pos && i < this.content.length; i++) {
      if (this.content[i] === '\n') {
        line++;
        col = 0;
      } else {
        col++;
      }
    }

    return { line, col };
  }

  drawSelection(line1, col1, line2, col2) {
    const charWidth = 7.8;
    const lineHeight = 21;

    for (let l = line1; l <= line2; l++) {
      const c1 = l === line1 ? col1 : 0;
      const c2 = l === line2 ? col2 : (this.lines[l]?.length || 0);

      if (c1 < c2) {
        const selection = document.createElement('div');
        selection.className = 'selection';
        selection.style.left = (8 + c1 * charWidth) + 'px';
        selection.style.top = (8 + l * lineHeight) + 'px';
        selection.style.width = ((c2 - c1) * charWidth) + 'px';
        selection.style.height = lineHeight + 'px';
        this.cursorLayer.appendChild(selection);
      }
    }
  }

  updateFind() {
    this.findQuery = this.findInput.value;
    this.findMatches = [];
    this.findCurrentIndex = -1;

    if (this.findQuery.length > 0) {
      let pos = 0;
      while (pos < this.content.length) {
        const index = this.content.indexOf(this.findQuery, pos);
        if (index === -1) break;
        this.findMatches.push(index);
        pos = index + 1;
      }

      if (this.findMatches.length > 0) {
        this.findCurrentIndex = 0;
        this.setCaret(this.findMatches[0] + this.findQuery.length);
      }
    }

    this.updateFindDisplay();
    this.render();
  }

  updateFindDisplay() {
    if (this.findMatches.length > 0) {
      this.findCount.textContent = `${this.findCurrentIndex + 1} / ${this.findMatches.length}`;
    } else {
      this.findCount.textContent = this.findQuery ? 'No matches' : '';
    }
  }

  findNext() {
    if (this.findMatches.length === 0) return;

    this.findCurrentIndex = (this.findCurrentIndex + 1) % this.findMatches.length;
    const pos = this.findMatches[this.findCurrentIndex];
    this.setCaret(pos + this.findQuery.length);
    this.updateFindDisplay();
    this.render();
  }

  findPrev() {
    if (this.findMatches.length === 0) return;

    this.findCurrentIndex = (this.findCurrentIndex - 1 + this.findMatches.length) % this.findMatches.length;
    const pos = this.findMatches[this.findCurrentIndex];
    this.setCaret(pos + this.findQuery.length);
    this.updateFindDisplay();
    this.render();
  }

  toggleReplace() {
    this.showReplace = !this.showReplace;
    this.replaceControls.style.display = this.showReplace ? 'flex' : 'none';
  }

  replaceOne() {
    if (this.findMatches.length === 0) return;

    const pos = this.findMatches[this.findCurrentIndex];
    const before = this.content.slice(0, pos);
    const after = this.content.slice(pos + this.findQuery.length);

    this.content = before + this.replaceQuery + after;

    // Update find matches positions
    const offset = this.replaceQuery.length - this.findQuery.length;
    for (let i = this.findCurrentIndex + 1; i < this.findMatches.length; i++) {
      this.findMatches[i] += offset;
    }

    this.updateContent();
    this.handleInput({});
    this.updateFind();
  }

  replaceAll() {
    if (this.findMatches.length === 0) return;

    let result = this.content;
    const offset = this.replaceQuery.length - this.findQuery.length;

    for (let i = this.findMatches.length - 1; i >= 0; i--) {
      const pos = this.findMatches[i];
      result = result.slice(0, pos) + this.replaceQuery + result.slice(pos + this.findQuery.length);
    }

    this.content = result;
    this.updateContent();
    this.handleInput({});
    this.updateFind();
  }

  saveToHistory() {
    this.history = this.history.slice(0, this.historyIndex + 1);
    this.history.push(this.content);
    this.historyIndex++;
  }

  undo() {
    if (this.historyIndex <= 0) return;
    this.historyIndex--;
    this.content = this.history[this.historyIndex];
    this.updateContent();
  }

  redo() {
    if (this.historyIndex >= this.history.length - 1) return;
    this.historyIndex++;
    this.content = this.history[this.historyIndex];
    this.updateContent();
  }

  markUnsaved() {
    if (this.isSaved) {
      this.isSaved = false;
      this.saveStatus.textContent = 'Unsaved changes';
      this.saveStatus.classList.remove('saved');
      this.saveStatus.classList.add('unsaved');
    }
  }

  markSaved() {
    this.isSaved = true;
    this.saveStatus.textContent = 'Saved';
    this.saveStatus.classList.remove('unsaved');
    this.saveStatus.classList.add('saved');
    this.baseRevision = this.currentRevision;
  }

  async save() {
    if (this.isSaved) {
      alert('No unsaved changes');
      return;
    }

    try {
      const response = await fetch(`/api/documents/${this.documentId}/save`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content: this.content,
          baseRevision: this.baseRevision,
          documentId: this.documentId
        })
      });

      if (response.status === 409) {
        // Conflict - another tab saved changes
        this.showConflict();
        return;
      }

      if (!response.ok) {
        const error = await response.json();
        alert(`Save failed: ${error.error}`);
        return;
      }

      const result = await response.json();
      this.currentRevision = result.revision;
      this.markSaved();
      this.revisionDisplay.textContent = `Revision ${this.currentRevision}`;
      this.refreshRevisionHistory();
    } catch (error) {
      console.error('Save error:', error);
      alert('Failed to save document');
    }
  }

  showConflict() {
    this.hasConflict = true;
    this.conflictDraft = this.content;
    this.conflictNotification.style.display = 'flex';
  }

  dismissConflict() {
    this.hasConflict = false;
    this.conflictNotification.style.display = 'none';
  }

  async reloadDocument() {
    this.dismissConflict();
    this.content = '';
    await this.loadDocument();
  }

  async refreshRevisionHistory() {
    try {
      const response = await fetch(`/api/documents/${this.documentId}/history`);
      if (!response.ok) return;

      const revisions = await response.json();
      this.revisionList.innerHTML = '';

      for (const rev of revisions) {
        const item = document.createElement('div');
        item.className = 'revision-item';

        const number = document.createElement('span');
        number.className = 'revision-item-number';
        number.textContent = `Revision ${rev.revisionNumber}`;
        item.appendChild(number);

        const time = document.createElement('span');
        time.className = 'revision-item-time';
        const date = new Date(rev.createdAt);
        time.textContent = date.toLocaleString();
        item.appendChild(time);

        if (rev.revisionNumber === this.currentRevision) {
          item.style.background = 'var(--primary-light)';
          item.style.borderColor = 'var(--primary)';
        }

        item.addEventListener('click', () => this.previewRevision(rev.revisionNumber));
        this.revisionList.appendChild(item);
      }
    } catch (error) {
      console.error('Error loading revision history:', error);
    }
  }

  async previewRevision(revisionNumber) {
    try {
      const response = await fetch(`/api/documents/${this.documentId}/revisions/${revisionNumber}`);
      if (!response.ok) return;

      const revision = await response.json();
      this.previewContent = revision.content;
      this.previewRevision = revisionNumber;

      this.previewTitle.textContent = `Revision ${revisionNumber}`;
      this.previewBody.textContent = revision.content;
      this.previewModal.style.display = 'flex';
    } catch (error) {
      console.error('Error loading revision:', error);
    }
  }

  closePreview() {
    this.previewModal.style.display = 'none';
    this.previewContent = '';
    this.previewRevision = null;
  }

  async confirmRestore() {
    try {
      const response = await fetch(
        `/api/documents/${this.documentId}/restore/${this.previewRevision}`,
        { method: 'POST' }
      );

      if (!response.ok) {
